# RANSOMWARE ADDRESSES DETECTION - EXPANSION EXPERIMENTS METRICS
#
# For every dataset generated by expansion_experiments.py:
#   1. Counts the addresses, transactions, inputs and outputs of each split
#   2. Serializes each split into a HeteroData graph, exactly like serialize_graph.py
#   3. Computes the graph-construction metrics of the k / w ablation:
#      nodes, edges, density, SCCs, expansion runtime, peak memory and
#      width-limit activation / candidate retention rates
# Results are saved in outputs/experiments_metrics/.

import torch
import numpy as np
import pandas as pd
import json
import scipy.sparse as sp
from scipy.sparse.csgraph import connected_components
from torch_geometric.data import HeteroData

from pathlib import Path
import sys

PROJECT_ROOT = Path(__file__).resolve().parent.parent
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from shared.paths import module_outputs_dir
from experiments_config import (
    SPLITS,
    EXPERIMENTS,
    HOPS_EXPERIMENTS,
    WIDTH_EXPERIMENTS,
    experiment_run_dir,
)

# Set to True to serialize again the runs that already have their graph.pth files
RESERIALIZE = False

METRICS_DIR = module_outputs_dir(__file__) / "experiments_metrics"
METRICS_DIR.mkdir(parents=True, exist_ok=True)

RUN_DIRS = {(hops, limit): experiment_run_dir(hops, limit) for hops, limit in EXPERIMENTS}

for (hops, limit), data_path in RUN_DIRS.items():
    if not data_path.exists():
        raise FileNotFoundError(f"Missing run for {hops} hops / limit {limit}: {data_path}")

## 1. DATASET COUNTS

def count_rows(csv_path):
    with open(csv_path, "r") as f:
        return sum(1 for _ in f) - 1

counts = []
for (hops, limit), data_path in RUN_DIRS.items():
    for split in SPLITS:
        split_path = data_path / split
        counts.append({
            "hops": hops,
            "limit": limit,
            "split": split,
            "n_addrs": count_rows(split_path / "addr_feats.csv"),
            "n_txs": count_rows(split_path / "tx_feats.csv"),
            "n_inputs": count_rows(split_path / "input_feats.csv"),
            "n_outputs": count_rows(split_path / "output_feats.csv"),
            "n_spent_pairs": count_rows(split_path / "spent_pairs.csv"),
        })

counts_df = pd.DataFrame(counts)
counts_df.to_csv(METRICS_DIR / "dataset_counts.csv", index=False)
print("\nDataset counts:")
print(counts_df.to_string(index=False))

## 2. GRAPH SERIALIZATION

def build_graph(txs_df, addrs_df, inputs_df, outputs_df, spent_pairs_df, tx_mapping, addr_mapping):
    data = HeteroData()

    inputs_df['tx_idx'] = inputs_df['tx_hash'].map(tx_mapping).astype(int)
    inputs_df['addr_idx'] = inputs_df['addr_str'].map(addr_mapping).astype(int)

    inputs_df['spent_tx_idx'] = inputs_df['spent_tx_hash'].map(tx_mapping)
    missing_spent_tx = inputs_df['spent_tx_idx'].isna()
    inputs_df.loc[missing_spent_tx, 'spent_output_index'] = -1

    inputs_df['spent_tx_idx'] = inputs_df['spent_tx_idx'].fillna(-1).astype(int)
    inputs_df['spent_output_index'] = inputs_df['spent_output_index'].astype(int)

    outputs_df['tx_idx'] = outputs_df['tx_hash'].map(tx_mapping).astype(int)
    outputs_df['addr_idx'] = outputs_df['addr_str'].map(addr_mapping).astype(int)

    # Transactions
    data['tx'].x = torch.tensor(txs_df[['block_height', 'fee', 'locktime', 'total_size', 'version']].values, dtype=torch.float)
    bool_features = torch.tensor(txs_df[['is_coinbase']].astype(float).values, dtype=torch.float)
    data['tx'].x = torch.cat([data['tx'].x, bool_features], dim=1)
    data['tx'].id = txs_df.index.values

    # Addresses
    addrs_df['full_type'], _ = pd.factorize(addrs_df['full_type'])
    full_type = torch.tensor(addrs_df[['full_type']].values, dtype=torch.float)

    cols = [c for c in list(addrs_df.columns)
        if c not in ["addr_str", "class", "full_type", "incoming_counterparties", "outgoing_counterparties"]]
    aggr_feats = torch.tensor(addrs_df[cols].values, dtype=torch.float)

    data['addr'].x = torch.cat([full_type, aggr_feats], dim=1)
    data['addr'].id = addrs_df.index.values
    data['addr'].y = torch.tensor(addrs_df['class'].values, dtype=torch.long)

    # Inputs
    inputs_df['sequence_num'], _ = pd.factorize(inputs_df["sequence_num"])
    data['addr', 'input', 'tx'].edge_index = torch.tensor(inputs_df[['addr_idx', 'tx_idx']].values.T, dtype=torch.long)
    input_attrs = torch.tensor(inputs_df[['age', 'sequence_num', 'value']].values, dtype=torch.float)
    data['addr', 'input', 'tx'].edge_attr = input_attrs

    # Outputs
    data['tx', 'output', 'addr'].edge_index = torch.tensor(outputs_df[['tx_idx', 'addr_idx']].values.T, dtype=torch.long)
    output_attrs = torch.tensor(outputs_df[['value']].values, dtype=torch.float)
    bool_spent = torch.tensor(outputs_df[['is_spent']].astype(float).values, dtype=torch.float)
    data['tx', 'output', 'addr'].edge_attr = torch.cat([output_attrs, bool_spent], dim=1)

    # Spent Outputs
    spent_edges = spent_pairs_df[['tx_hash_spent', 'tx_hash_spend']].applymap(tx_mapping.get).dropna()
    data['tx', 'spent_output', 'tx'].edge_index = torch.tensor(spent_edges.values.T, dtype=torch.long)

    return data

def serialize_split(split_path):
    txs_df = pd.read_csv(split_path / 'tx_feats.csv')
    addrs_df = pd.read_csv(split_path / 'addr_feats.csv')
    inputs_df = pd.read_csv(split_path / 'input_feats.csv')
    outputs_df = pd.read_csv(split_path / 'output_feats.csv')
    spent_pairs_df = pd.read_csv(split_path / 'spent_pairs.csv')

    tx_mapping = pd.Series(txs_df.index.values, index=txs_df['hash']).to_dict()
    addr_mapping = pd.Series(addrs_df.index.values, index=addrs_df['addr_str']).to_dict()

    with open(split_path / "tx_mapping.json",  "w") as f:
        json.dump(tx_mapping, f)
    with open(split_path / "addr_mapping.json","w") as f:
        json.dump(addr_mapping, f)

    data = build_graph(
        txs_df, addrs_df, inputs_df, outputs_df,
        spent_pairs_df, tx_mapping, addr_mapping
    )
    torch.save(data, split_path / 'graph.pth')

for (hops, limit), data_path in RUN_DIRS.items():
    for split in SPLITS:
        split_path = data_path / split
        if (split_path / 'graph.pth').exists() and not RESERIALIZE:
            print(f"\nSkipping {hops} hops / limit {limit} / {split}: graph.pth already exists")
            continue
        print(f"\nSerializing {hops} hops / limit {limit} / {split}...")
        serialize_split(split_path)

## 3. METRICS

def load_graph(graph_path):
    try:
        return torch.load(graph_path, weights_only=False)
    except TypeError:
        return torch.load(graph_path)

def graph_metrics(data):
    n_addr = data['addr'].num_nodes
    n_tx = data['tx'].num_nodes
    n_nodes = n_addr + n_tx

    # Homogeneous directed graph: address nodes first, then transaction nodes
    input_index = data['addr', 'input', 'tx'].edge_index.numpy()
    output_index = data['tx', 'output', 'addr'].edge_index.numpy()
    spent_index = data['tx', 'spent_output', 'tx'].edge_index.numpy()

    src = np.concatenate([input_index[0], output_index[0] + n_addr, spent_index[0] + n_addr])
    dst = np.concatenate([input_index[1] + n_addr, output_index[1], spent_index[1] + n_addr])
    n_edges = len(src)

    adjacency = sp.coo_matrix((np.ones(n_edges, dtype=np.int8), (src, dst)), shape=(n_nodes, n_nodes)).tocsr()
    n_scc, scc_labels = connected_components(adjacency, directed=True, connection='strong')
    scc_sizes = np.bincount(scc_labels)
    largest_scc = int(scc_sizes.max()) if n_nodes > 0 else 0

    return {
        "addr_nodes": n_addr,
        "tx_nodes": n_tx,
        "total_nodes": n_nodes,
        "input_edges": input_index.shape[1],
        "output_edges": output_index.shape[1],
        "spent_output_edges": spent_index.shape[1],
        "total_edges": n_edges,
        "density": n_edges / (n_nodes * (n_nodes - 1)) if n_nodes > 1 else 0.0,
        "n_scc": int(n_scc),
        "n_nontrivial_scc": int((scc_sizes > 1).sum()),
        "largest_scc": largest_scc,
        "largest_scc_ratio": largest_scc / n_nodes if n_nodes > 0 else 0.0,
    }

def expansion_metrics(split_path):
    stats_path = split_path / "expansion_stats.json"
    if not stats_path.exists():
        print(f"  [WARNING] {stats_path} not found: runtime, memory and width-limit metrics left empty")
        return {}

    with open(stats_path) as f:
        stats = json.load(f)

    width = stats["width_limit"]
    return {
        "n_seeds": stats["n_seeds"],
        "expansion_time_s": stats["expansion_time_s"],
        "expansion_time_per_seed_s": stats["expansion_time_per_seed_s"],
        "peak_rss_mb": stats["peak_rss_mb"],
        "peak_rss_anon_mb": stats["peak_rss_anon_mb"],
        "rss_anon_increase_mb": stats["peak_rss_anon_mb"] - stats["baseline_rss_anon_mb"],
        "expansion_steps": width["nonempty_steps"],
        "activated_steps": width["activated_steps"],
        "activation_rate": width["activated_steps"] / width["nonempty_steps"] if width["nonempty_steps"] else 0.0,
        "candidates": width["candidates"],
        "retained": width["retained"],
        "retention_rate": width["retained"] / width["candidates"] if width["candidates"] else 0.0,
        "discard_rate": 1 - width["retained"] / width["candidates"] if width["candidates"] else 0.0,
    }

metrics = []
for (hops, limit), data_path in RUN_DIRS.items():
    for split in SPLITS:
        split_path = data_path / split
        print(f"\nComputing metrics for {hops} hops / limit {limit} / {split}...")
        data = load_graph(split_path / 'graph.pth')
        metrics.append({
            "hops": hops,
            "limit": limit,
            "split": split,
            **graph_metrics(data),
            **expansion_metrics(split_path),
        })
        del data

metrics_df = pd.DataFrame(metrics)
metrics_df.to_csv(METRICS_DIR / "metrics.csv", index=False)

# Depth sweep (k): w fixed, plus the nodes and edges added by each extra hop
k_df = metrics_df[metrics_df[["hops", "limit"]].apply(tuple, axis=1).isin(HOPS_EXPERIMENTS)]
k_df = k_df.sort_values(["split", "hops"]).copy()
k_df["delta_nodes"] = k_df.groupby("split")["total_nodes"].diff()
k_df["delta_edges"] = k_df.groupby("split")["total_edges"].diff()
k_columns = ["split", "hops", "limit", "addr_nodes", "tx_nodes", "total_nodes", "delta_nodes",
             "total_edges", "delta_edges", "expansion_time_s", "expansion_time_per_seed_s",
             "n_scc", "n_nontrivial_scc", "largest_scc", "largest_scc_ratio", "density"]
k_df = k_df[[c for c in k_columns if c in k_df.columns]]
k_df.to_csv(METRICS_DIR / "k_sweep.csv", index=False)

# Width sweep (w): k fixed
w_df = metrics_df[metrics_df[["hops", "limit"]].apply(tuple, axis=1).isin(WIDTH_EXPERIMENTS)]
w_df = w_df.sort_values(["split", "limit"])
w_columns = ["split", "hops", "limit", "addr_nodes", "tx_nodes", "total_nodes", "total_edges",
             "activation_rate", "candidates", "retained", "retention_rate", "discard_rate",
             "expansion_time_s", "expansion_time_per_seed_s", "peak_rss_mb", "peak_rss_anon_mb",
             "rss_anon_increase_mb", "n_scc", "n_nontrivial_scc", "largest_scc", "largest_scc_ratio", "density"]
w_df = w_df[[c for c in w_columns if c in w_df.columns]]
w_df.to_csv(METRICS_DIR / "w_sweep.csv", index=False)

pd.set_option("display.width", 250)
pd.set_option("display.max_columns", None)
print("\n========================================")
print("Depth sweep (k)")
print("========================================")
print(k_df.to_string(index=False))
print("\n========================================")
print("Width sweep (w)")
print("========================================")
print(w_df.to_string(index=False))
print(f"\nResults saved at: {METRICS_DIR}")
